"""Generates supabase/seed.sql — realistic DAYSTAR demo data.
Run:  python3 supabase/gen_seed.py > supabase/seed.sql
All values are demo data on the September 2026 baseline; edit freely in the app.
"""
import uuid, random, datetime as dt

random.seed(20260905)
NS = uuid.NAMESPACE_URL
def U(kind, key): return str(uuid.uuid5(NS, f"daystar-os/{kind}/{key}"))
def q(v):
    if v is None: return "null"
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, (int, float)): return str(v)
    if isinstance(v, (dt.date,)): return f"'{v.isoformat()}'"
    if isinstance(v, list): return "array[" + ",".join(q(x) for x in v) + "]::text[]" if v else "'{}'::text[]"
    return "'" + str(v).replace("'", "''") + "'"
def ins(table, rows, cols=None):
    if not rows: return ""
    cols = cols or list(rows[0].keys())
    vals = ",\n".join("(" + ", ".join(q(r.get(c)) for c in cols) + ")" for r in rows)
    return f"insert into public.{table} ({', '.join(cols)}) values\n{vals};\n\n"

